<?php
namespace App\Http\Controllers;use App\Models\Survey;use App\Services\CsvMeasurementImportService;use App\Support\PersistentStorage;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Validation\ValidationException;
class MeasurementImportController extends Controller{public function store(Request $r,Survey $survey,CsvMeasurementImportService $service):JsonResponse{abort_unless($r->user()->can('measurements.import'),403);$d=$r->validate(['file'=>'required|file|mimes:csv,txt|max:51200']);$f=$d['file'];$disk=PersistentStorage::diskName();$path=$f->store("measurement-imports/{$survey->id}",$disk);if($path===false)throw ValidationException::withMessages(['file'=>'The CSV file could not be stored.']);$import=$survey->imports()->create(['uploaded_by'=>$r->user()->id,'original_name'=>$f->getClientOriginalName(),'file_path'=>$path,'storage_disk'=>$disk,'status'=>'pending']);return response()->json($service->process($import,$r->user()->id),201);}public function errors(Request $r,\App\Models\MeasurementImport $measurementImport):JsonResponse{abort_unless($r->user()->can('measurements.import'),403);return response()->json($measurementImport->errors()->orderBy('row_number')->get());}}
